insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$alzheimer-s-disease$rounds_kb$, $rounds_kb$Alzheimer's Disease$rounds_kb$, $rounds_kb$neurology$rounds_kb$, array[$rounds_kb$neurology$rounds_kb$, $rounds_kb$psychiatry$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$]::text[], array[$rounds_kb$nervous$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "alzheimer-s-disease", "triage": {"name": "Alzheimer's Disease", "case_suitable": true, "reason": "Progressive memory loss and functional decline diagnosed clinically with cognitive testing and reversible-cause workup.", "kind": "disease", "category": "neurodegenerative dementia", "organ_systems": ["nervous"], "primary_clerkship": "neurology", "secondary_clerkships": ["psychiatry", "internalMedicine", "familyMedicine"], "commonness": "very_common", "settings": ["clinic", "inpatient"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:15:33Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:24:47Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:24:53Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:25:13Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:25:25Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:25:31Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["differential delirium: no profile yet", "differential major-depressive-disorder: no profile yet", "differential normal-pressure-hydrocephalus: no profile yet", "differential vascular-dementia: no profile yet", "differential dementia-with-lewy-bodies: no profile yet", "differential frontotemporal-dementia: no profile yet", "differential medication-induced-cognitive-impairment: no profile yet", "differential hypothyroidism: no profile yet", "differential vitamin-b12-deficiency: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 65, "typical_max": 90, "peak": "75–85", "possible_min": 40, "possible_max": 110}, "sex": "female_predominant", "demographics": ["Risk roughly doubles every 5 years after age 65", "More common in women, largely because women live longer", "More common in Black and Hispanic older adults in the US, in part due to differences in vascular risk and access to care"], "risk_factors": [{"text": "Advancing age, especially over 65", "strength": "strong"}, {"text": "First-degree relative with Alzheimer's disease", "strength": "moderate"}, {"text": "Mild cognitive impairment", "strength": "strong"}, {"text": "Hearing loss in older age", "strength": "moderate"}, {"text": "History of traumatic brain injury, especially repeated", "strength": "moderate"}, {"text": "Late-life depression", "strength": "moderate"}, {"text": "Fewer years of formal education or low cognitive reserve", "strength": "weak"}, {"text": "Rare autosomal dominant mutations (APP, PSEN1, PSEN2) causing early-onset disease", "strength": "weak"}], "comorbidities": ["Hypertension", "Type 2 diabetes", "Hyperlipidemia", "Prior stroke or transient ischemic attack", "Depression", "Obstructive sleep apnea"], "family_history": ["A parent or sibling with dementia or Alzheimer's disease", "Rare early-onset familial cases with multiple affected relatives before age 65"], "social_history": ["Lives alone or with a spouse who has become the caregiver", "Limited social engagement or recent loss of driving privileges", "Retired; may have stopped hobbies and community activities"], "exposures": [], "risk_medications": ["anticholinergics", "benzodiazepines", "diphenhydramine"]}, "presentation": {"chief_complaints": [{"text": "My wife says I keep asking the same questions over and over", "frequency": "almost_always"}, {"text": "I keep forgetting where I put things and I can't remember appointments", "frequency": "almost_always"}, {"text": "I got lost driving to the grocery store I've gone to for years", "frequency": "common"}, {"text": "My family says I'm not myself anymore", "frequency": "common"}], "hpi": {"onset": "Insidious, over months to a few years; family often dates it to a specific event but on careful questioning it was already present before that", "duration": "Usually at least 6–12 months of symptoms by the time of presentation", "progression": "Slowly progressive and steadily worsening; short-term memory goes first, then language, orientation, and daily function", "location": "Not applicable", "radiation": "Not applicable", "quality": "Forgetfulness of recent events and conversations while remote memories stay intact early on; repeating questions; misplacing items; trouble with words, bills, and medications", "severity": "Mild at first and easy to dismiss as normal aging; by presentation it is interfering with work, finances, driving, or medications", "timing": "Constant, worse for recent information; often more noticeable in the evening or in unfamiliar settings", "aggravating": ["Unfamiliar places", "Fatigue", "Being rushed or asked to multitask", "Illness or hospitalization"], "relieving": ["Familiar routines", "Written reminders and calendars", "Help from family"], "associated_symptoms": [{"text": "Repeating the same question or story within minutes", "frequency": "almost_always"}, {"text": "Misplacing items, sometimes in odd places", "frequency": "almost_always"}, {"text": "Trouble finding words or following a conversation", "frequency": "common"}, {"text": "Getting lost in familiar places", "frequency": "common"}, {"text": "Difficulty managing money, bills, or medications", "frequency": "common"}, {"text": "Misplacing or forgetting appointments and names of acquaintances", "frequency": "common"}, {"text": "Personality change, irritability, or apathy", "frequency": "common"}, {"text": "Withdrawal from hobbies and social activities", "frequency": "common"}, {"text": "Trouble with orientation to date or day of the week", "frequency": "sometimes"}, {"text": "Delusions such as believing things have been stolen", "frequency": "sometimes"}, {"text": "Wandering or getting up at night", "frequency": "sometimes"}, {"text": "Weight loss or poor appetite", "frequency": "sometimes"}, {"text": "Visual hallucinations", "frequency": "rare"}], "pertinent_negatives": ["Stepwise decline with sudden drops", "Focal weakness, numbness, or a single-sided deficit", "New seizures", "Prominent visual hallucinations early in the course", "Parkinsonism before memory loss", "Abrupt onset over hours to days", "Fluctuating alertness from hour to hour", "Recent head trauma", "Fever or systemic illness", "New incontinence early in the illness", "Symptoms that began while starting a new medication"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Low energy and reduced initiative", "frequency": "common"}, {"text": "Weight loss", "frequency": "sometimes"}], "negatives": ["Fever", "Night sweats", "Chills"]}, {"system": "neurologic", "positives": [{"text": "Short-term memory loss", "frequency": "almost_always"}, {"text": "Word-finding difficulty", "frequency": "common"}, {"text": "Getting lost in familiar places", "frequency": "common"}, {"text": "Trouble with calculations and planning", "frequency": "common"}, {"text": "Trouble recognizing familiar faces late in the illness", "frequency": "sometimes"}], "negatives": ["Focal weakness", "Numbness", "New seizures", "Tremor at rest", "Falls early in the illness"], "argues_against": ["Sudden focal neurologic deficit", "Early prominent falls or tremor"]}, {"system": "psychiatric", "positives": [{"text": "Apathy or loss of interest", "frequency": "common"}, {"text": "Irritability or agitation", "frequency": "common"}, {"text": "Depressed mood", "frequency": "sometimes"}, {"text": "Suspiciousness or delusions of theft", "frequency": "sometimes"}, {"text": "Anxiety, especially when separated from a caregiver", "frequency": "sometimes"}], "negatives": ["Visual hallucinations early in the illness", "Manic episodes", "Suicidal intent"], "argues_against": ["Prominent early visual hallucinations", "Fluctuating attention"]}, {"system": "gastrointestinal", "positives": [{"text": "Poor appetite", "frequency": "sometimes"}, {"text": "Constipation", "frequency": "sometimes"}], "negatives": ["Vomiting", "Blood in stool", "Difficulty swallowing early in the illness"]}, {"system": "genitourinary", "positives": [{"text": "Urinary urgency or incontinence late in the illness", "frequency": "sometimes"}], "negatives": ["Incontinence early in the illness", "Dysuria", "Hematuria"], "argues_against": ["Early urinary incontinence"]}, {"system": "musculoskeletal", "positives": [{"text": "Slowed walking and unsteadiness late in the illness", "frequency": "sometimes"}], "negatives": ["Focal weakness", "Joint swelling", "Back pain"], "argues_against": ["Early gait disorder"]}, {"system": "endocrine", "positives": [], "negatives": ["Heat or cold intolerance", "Polyuria", "Polydipsia"]}, {"system": "hematologic", "positives": [], "negatives": ["Easy bruising", "Bleeding"]}, {"system": "allergic_immunologic", "positives": [], "negatives": ["Rash", "Recurrent infections"]}], "atypical": [{"population": "older_adults", "how_it_differs": "In the oldest patients, apathy, gait slowing, and withdrawal may dominate while the patient denies any memory problem; family reports the decline.", "missing_classic_features": ["Self-reported memory complaint"]}, {"population": "children", "how_it_differs": "Not applicable; Alzheimer's disease does not occur in children.", "missing_classic_features": ["All classic features"]}]}, "exam": {"general": {"mild": "Well-groomed, alert, pleasant; may repeat questions during the visit; caregiver answers for the patient", "moderate": "Disheveled or dressed inappropriately for the weather, restless or withdrawn, needs prompting to stay on topic", "severe": "Poorly groomed, disoriented to place and time, may be agitated or apathetic, needs help with transfers", "critical": "Bedbound, mute or minimally responsive, contractures, dependent for all care"}, "findings": [{"id": "impaired-recent-memory", "region": "mental_status", "maneuver": "Ask the patient to repeat three words and recall them after a few minutes", "finding": "Cannot recall the words even with cueing", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "disoriented-to-time", "region": "mental_status", "maneuver": "Ask the date, day of the week, month, and year", "finding": "Wrong date or day of the week", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "essential"}, {"id": "impaired-fluency", "region": "mental_status", "maneuver": "Ask the patient to name as many animals as they can in one minute", "finding": "Fewer than expected words for age and education", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "impaired-serial-sevens", "region": "mental_status", "maneuver": "Ask the patient to count backward from 100 by sevens", "finding": "Makes errors or cannot perform the task", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "impaired-clock-drawing", "region": "mental_status", "maneuver": "Ask the patient to draw a clock showing a specific time", "finding": "Misplaced numbers, wrong spacing, or incorrect hands", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "word-finding", "region": "mental_status", "maneuver": "Listen during conversation and ask the patient to name common objects", "finding": "Circumlocution or difficulty naming familiar items", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "apraxia", "region": "neuro", "maneuver": "Ask the patient to pantomime brushing teeth or wave goodbye", "finding": "Cannot perform the learned movement despite intact strength", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "optional"}, {"id": "agnosia", "region": "neuro", "maneuver": "Show a familiar object and ask the patient to identify it", "finding": "Cannot recognize the object by sight", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "optional"}, {"id": "normal-cranial-nerves", "region": "heent", "maneuver": "Test extraocular movements, visual fields, facial strength, and hearing", "finding": "Cranial nerves intact", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-motor", "region": "extremities", "maneuver": "Test strength in all four limbs", "finding": "No focal weakness", "frequency": "almost_always", "significance": "neutral", "importance": "essential"}, {"id": "normal-reflexes", "region": "extremities", "maneuver": "Test deep tendon reflexes", "finding": "Symmetric, normal reflexes", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "no-rest-tremor", "region": "extremities", "maneuver": "Observe the hands at rest and with posture", "finding": "No resting tremor", "frequency": "almost_always", "significance": "argues_against", "importance": "important"}, {"id": "normal-gait-early", "region": "musculoskeletal", "maneuver": "Observe the patient walking and turning", "finding": "Normal gait and posture early in the illness", "frequency": "common", "significance": "neutral", "importance": "important"}, {"id": "gait-apraxi